template <typename UnionPtrType>
SpeechRecognizerEventPtr SpeechRecognizerEvent::Clone() const {
  // Use UnionPtrType to prevent the compiler from trying to compile this
  // without being asked.
  UnionPtrType rv(New());
  switch (tag_) {
    case Tag::AUDIO_EVENT:
      rv->set_audio_event(mojo::Clone(*data_.audio_event));
      break;
    case Tag::PARTIAL_RESULT:
      rv->set_partial_result(mojo::Clone(*data_.partial_result));
      break;
    case Tag::ENDPOINTER_EVENT:
      rv->set_endpointer_event(mojo::Clone(*data_.endpointer_event));
      break;
    case Tag::FINAL_RESULT:
      rv->set_final_result(mojo::Clone(*data_.final_result));
      break;
  }
  return rv;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, SpeechRecognizerEvent>::value>::type*>
bool SpeechRecognizerEvent::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::AUDIO_EVENT:
      return mojo::Equals(*(data_.audio_event), *(other.data_.audio_event));
    case Tag::PARTIAL_RESULT:
      return mojo::Equals(*(data_.partial_result), *(other.data_.partial_result));
    case Tag::ENDPOINTER_EVENT:
      return mojo::Equals(*(data_.endpointer_event), *(other.data_.endpointer_event));
    case Tag::FINAL_RESULT:
      return mojo::Equals(*(data_.final_result), *(other.data_.final_result));
  }

  return false;
}
template <typename StructPtrType>
SodaConfigPtr SodaConfig::Clone() const {
  return New(
      mojo::Clone(channel_count),
      mojo::Clone(sample_rate),
      mojo::Clone(api_key),
      mojo::Clone(library_dlc_path),
      mojo::Clone(language_dlc_path),
      mojo::Clone(enable_formatting),
      mojo::Clone(recognition_mode)
  );
}

template <typename T, SodaConfig::EnableIfSame<T>*>
bool SodaConfig::Equals(const T& other_struct) const {
  if (!mojo::Equals(this->channel_count, other_struct.channel_count))
    return false;
  if (!mojo::Equals(this->sample_rate, other_struct.sample_rate))
    return false;
  if (!mojo::Equals(this->api_key, other_struct.api_key))
    return false;
  if (!mojo::Equals(this->library_dlc_path, other_struct.library_dlc_path))
    return false;
  if (!mojo::Equals(this->language_dlc_path, other_struct.language_dlc_path))
    return false;
  if (!mojo::Equals(this->enable_formatting, other_struct.enable_formatting))
    return false;
  if (!mojo::Equals(this->recognition_mode, other_struct.recognition_mode))
    return false;
  return true;
}

template <typename T, SodaConfig::EnableIfSame<T>*>
bool operator<(const T& lhs, const T& rhs) {
  if (lhs.channel_count < rhs.channel_count)
    return true;
  if (rhs.channel_count < lhs.channel_count)
    return false;
  if (lhs.sample_rate < rhs.sample_rate)
    return true;
  if (rhs.sample_rate < lhs.sample_rate)
    return false;
  if (lhs.api_key < rhs.api_key)
    return true;
  if (rhs.api_key < lhs.api_key)
    return false;
  if (lhs.library_dlc_path < rhs.library_dlc_path)
    return true;
  if (rhs.library_dlc_path < lhs.library_dlc_path)
    return false;
  if (lhs.language_dlc_path < rhs.language_dlc_path)
    return true;
  if (rhs.language_dlc_path < lhs.language_dlc_path)
    return false;
  if (lhs.enable_formatting < rhs.enable_formatting)
    return true;
  if (rhs.enable_formatting < lhs.enable_formatting)
    return false;
  if (lhs.recognition_mode < rhs.recognition_mode)
    return true;
  if (rhs.recognition_mode < lhs.recognition_mode)
    return false;
  return false;
}
